@using sv_72663b5985b044be823036a3ba9bc5ac.Services

<div class="list-group">
    @foreach (var section in Sections)
    {
        <button type="button"
                class="list-group-item list-group-item-action @(section == ActiveSection ? "active" : "")"
                @onclick="() => OnSectionChanged.InvokeAsync(section)">
            <i class="bi @GetIcon(section) me-2"></i>@section
        </button>
    }
</div>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "bi-person",
        "Notifications" => "bi-bell",
        "Security" => "bi-shield-lock",
        "Appearance" => "bi-palette",
        _ => "bi-gear"
    };
}

@using sv_72663b5985b044be823036a3ba9bc5ac.Services
@inject ISettingsService SettingsService

@if (_profile is null)
{
    <p>Loading...</p>
    return;
}

<h4 class="mb-4">Profile Settings</h4>

@if (!string.IsNullOrEmpty(_message))
{
    <div class="alert alert-success alert-dismissible fade show" role="alert">
        @_message
        <button type="button" class="btn-close" @onclick="() => _message = null"></button>
    </div>
}

<div class="row">
    <div class="col-md-8">
        <div class="mb-3">
            <label class="form-label">Display Name</label>
            <input type="text" class="form-control" @bind="_displayName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email</label>
            <input type="email" class="form-control" @bind="_email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Bio</label>
            <textarea class="form-control" rows="4" @bind="_bio"></textarea>
        </div>
        <div class="mb-3">
            <label class="form-label">Avatar URL</label>
            <input type="text" class="form-control" @bind="_avatarUrl" />
        </div>
        <div class="d-flex gap-2">
            <button class="btn btn-primary" @onclick="SaveChanges">Save Changes</button>
            <button class="btn btn-outline-secondary" @onclick="DiscardChanges">Discard Changes</button>
        </div>
    </div>
    <div class="col-md-4 text-center">
        <div class="border rounded p-3">
            <img src="@_avatarUrl" alt="Avatar preview" class="rounded-circle mb-2" style="width:128px;height:128px;object-fit:cover;" />
            <p class="text-muted small mb-0">Avatar Preview</p>
        </div>
    </div>
</div>

@code {
    private UserProfile? _profile;
    private string _displayName = "";
    private string _email = "";
    private string _bio = "";
    private string _avatarUrl = "";
    private string? _message;

    protected override async Task OnInitializedAsync()
    {
        _profile = await SettingsService.GetProfileAsync();
        LoadFromProfile(_profile);
    }

    private void LoadFromProfile(UserProfile profile)
    {
        _displayName = profile.DisplayName;
        _email = profile.Email;
        _bio = profile.Bio;
        _avatarUrl = profile.AvatarUrl;
    }

    private async Task SaveChanges()
    {
        var updated = new UserProfile(_displayName, _email, _avatarUrl, _bio);
        await SettingsService.SaveProfileAsync(updated);
        _profile = updated;
        _message = "Profile saved successfully!";
    }

    private void DiscardChanges()
    {
        if (_profile is not null)
        {
            LoadFromProfile(_profile);
        }
        _message = null;
    }
}

@using sv_72663b5985b044be823036a3ba9bc5ac.Services
@inject ISettingsService SettingsService

@if (_prefs is null)
{
    <p>Loading...</p>
    return;
}

<h4 class="mb-4">Notification Preferences</h4>

@if (!string.IsNullOrEmpty(_message))
{
    <div class="alert alert-success alert-dismissible fade show" role="alert">
        @_message
        <button type="button" class="btn-close" @onclick="() => _message = null"></button>
    </div>
}

<div class="mb-4">
    <div class="form-check form-switch mb-3">
        <input class="form-check-input" type="checkbox" id="emailNotif" @bind="_emailNotifications" />
        <label class="form-check-label" for="emailNotif">Email Notifications</label>
    </div>
    <div class="form-check form-switch mb-3">
        <input class="form-check-input" type="checkbox" id="pushNotif" @bind="_pushNotifications" />
        <label class="form-check-label" for="pushNotif">Push Notifications</label>
    </div>
    <div class="form-check form-switch mb-3">
        <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="_weeklyDigest" />
        <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
    </div>
</div>

<h5 class="mb-3">Muted Channels</h5>
<div class="mb-4">
    @foreach (var channel in _allChannels)
    {
        var isMuted = _mutedChannels.Contains(channel);
        <div class="form-check mb-2">
            <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                   checked="@isMuted"
                   @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
            <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
        </div>
    }
</div>

<button class="btn btn-primary" @onclick="SavePreferences">Save Preferences</button>

@code {
    private NotificationPrefs? _prefs;
    private bool _emailNotifications;
    private bool _pushNotifications;
    private bool _weeklyDigest;
    private List<string> _mutedChannels = [];
    private string? _message;

    private static readonly string[] _allChannels = ["announcements", "marketing", "events", "product-updates", "community"];

    protected override async Task OnInitializedAsync()
    {
        _prefs = await SettingsService.GetNotificationPrefsAsync();
        _emailNotifications = _prefs.EmailNotifications;
        _pushNotifications = _prefs.PushNotifications;
        _weeklyDigest = _prefs.WeeklyDigest;
        _mutedChannels = new List<string>(_prefs.MutedChannels);
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted && !_mutedChannels.Contains(channel))
            _mutedChannels.Add(channel);
        else if (!muted)
            _mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        var updated = new NotificationPrefs(_emailNotifications, _pushNotifications, _weeklyDigest, new List<string>(_mutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(updated);
        _prefs = updated;
        _message = "Notification preferences saved!";
    }
}

@using sv_72663b5985b044be823036a3ba9bc5ac.Services
@inject ISettingsService SettingsService

@if (_settings is null)
{
    <p>Loading...</p>
    return;
}

<h4 class="mb-4">Security Settings</h4>

@if (!string.IsNullOrEmpty(_message))
{
    <div class="alert @_messageClass alert-dismissible fade show" role="alert">
        @_message
        <button type="button" class="btn-close" @onclick="() => _message = null"></button>
    </div>
}

<!-- Change Password -->
<div class="card mb-4">
    <div class="card-header d-flex justify-content-between align-items-center" style="cursor:pointer" @onclick="() => _passwordExpanded = !_passwordExpanded">
        <span><i class="bi bi-key me-2"></i>Change Password</span>
        <i class="bi @(_passwordExpanded ? "bi-chevron-up" : "bi-chevron-down")"></i>
    </div>
    @if (_passwordExpanded)
    {
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="_currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="_newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="_confirmPassword" />
            </div>
            <button class="btn btn-warning" @onclick="UpdatePassword">Update Password</button>
        </div>
    }
</div>

<!-- Two-Factor Authentication -->
<div class="card mb-4">
    <div class="card-body d-flex justify-content-between align-items-center">
        <div>
            <h6 class="mb-1">Two-Factor Authentication</h6>
            <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                @(_twoFactorEnabled ? "Enabled" : "Disabled")
            </span>
            @if (_settings.LastPasswordChange.HasValue)
            {
                <small class="text-muted ms-3">Last password change: @_settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")</small>
            }
        </div>
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
        </div>
    </div>
</div>

<!-- Active Sessions -->
<div class="card mb-4">
    <div class="card-header">
        <i class="bi bi-display me-2"></i>Active Sessions
    </div>
    <div class="card-body p-0">
        <table class="table table-hover mb-0">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in _settings.Sessions)
                {
                    var isCurrent = session.Id == _settings.Sessions.FirstOrDefault()?.Id;
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@FormatLastActive(session.LastActive)</td>
                        <td>
                            @if (!isCurrent)
                            {
                                <button class="btn btn-sm btn-outline-danger" @onclick="() => ConfirmRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="badge bg-info">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
</div>

<!-- Revoke Confirmation Dialog -->
@if (_sessionToRevoke is not null)
{
    <div class="modal d-block" tabindex="-1" style="background-color:rgba(0,0,0,0.5)">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="RevokeConfirmed">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private SecuritySettings? _settings;
    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private ActiveSession? _sessionToRevoke;
    private string? _message;
    private string _messageClass = "alert-success";

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
    }

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _message = "New password cannot be empty.";
            _messageClass = "alert-danger";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _message = "New password and confirmation do not match.";
            _messageClass = "alert-danger";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _message = "Password updated successfully!";
        _messageClass = "alert-success";
        _settings = await SettingsService.GetSecuritySettingsAsync();
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task RevokeConfirmed()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _settings = await SettingsService.GetSecuritySettingsAsync();
            _sessionToRevoke = null;
            _message = "Session revoked.";
            _messageClass = "alert-success";
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

