            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
    </div>

    <!-- Live Preview -->
    <div class="col-md-5">
        <div class="border rounded p-3 @GetPreviewClasses()" style="@GetPreviewStyle()">
            <h6 class="mb-2">Live Preview</h6>
            <p class="@(_compactMode ? "mb-1" : "mb-3")">This is how your content will look with the selected settings.</p>
            <div class="@(_compactMode ? "mb-1" : "mb-2")">
                <span class="badge bg-primary me-1">Tag 1</span>
                <span class="badge bg-secondary me-1">Tag 2</span>
            </div>
            <button class="btn btn-sm btn-outline-primary">Sample Button</button>
        </div>
    </div>
</div>

@code {
    private AppearanceSettings? _settings;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private string? _message;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetAppearanceAsync();
        _theme = _settings.Theme;
        _fontSize = _settings.FontSize;
        _language = _settings.Language;
        _compactMode = _settings.CompactMode;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _settings = updated;
        _message = "Appearance settings saved!";
    }

    private string GetPreviewClasses()
    {
        var classes = _theme switch
        {
            "Dark" => "bg-dark text-light",
            _ => "bg-light text-dark"
        };
        return classes;
    }

    private string GetPreviewStyle()
    {
        var size = _fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        return $"font-size:{size};";
    }
}

