{"file_text": "@using sv_72663b5985b044be823036a3ba9bc5ac.Services
@inject ISettingsService SettingsService

@if (_settings is null)
{
    <p>Loading...</p>
    return;
}

<h4 class="mb-4">Security Settings</h4>

@if (!string.IsNullOrEmpty(_message))
{
    <div class="alert @_messageClass alert-dismissible fade show" role="alert">
        @_message
        <button type="button" class="btn-close" @onclick="() => _message = null"></button>
    </div>
}

<!-- Change Password -->
<div class="card mb-4">
    <div class="card-header d-flex justify-content-between align-items-center" style="cursor:pointer" @onclick="() => _passwordExpanded = !_passwordExpanded">
        <span><i class="bi bi-key me-2"></i>Change Password</span>
        <i class="bi @(_passwordExpanded ? "bi-chevron-up" : "bi-chevron-down")"></i>
    </div>
    @if (_passwordExpanded)
    {
        <div class="card-body">
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="_currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="_newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="_confirmPassword" />
            </div>
            <button class="btn btn-warning" @onclick="UpdatePassword">Update Password</button>
        </div>
    }
</div>

<!-- Two-Factor Authentication -->
<div class="card mb-4">
    <div class="card-body d-flex justify-content-between align-items-center">
        <div>
            <h6 class="mb-1">Two-Factor Authentication</h6>
            <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary")">
                @(_twoFactorEnabled ? "Enabled" : "Disabled")
            </span>
            @if (_settings.LastPasswordChange.HasValue)
            {
                <small class="text-muted ms-3">Last password change: @_settings.LastPasswordChange.Value.ToString("MMM dd, yyyy")</small>
            }
        </div>
        <div class="form-check form-switch">
            <input class="form-check-input" type="checkbox" @bind="_twoFactorEnabled" />
        </div>
    </div>
</div>

<!-- Active Sessions -->
<div class="card mb-4">
    <div class="card-header">
        <i class="bi bi-display me-2"></i>Active Sessions
    </div>
    <div class="card-body p-0">
        <table class="table table-hover mb-0">
            <thead>
                <tr>
                    <th>Device</th>
                    <th>Location</th>
                    <th>Last Active</th>
                    <th></th>
                </tr>
            </thead>
            <tbody>
                @foreach (var session in _settings.Sessions)
                {
                    var isCurrent = session.Id == _settings.Sessions.FirstOrDefault()?.Id;
                    <tr>
                        <td>@session.Device</td>
                        <td>@session.Location</td>
                        <td>@FormatLastActive(session.LastActive)</td>
                        <td>
                            @if (!isCurrent)
                            {
                                <button class="btn btn-sm btn-outline-danger" @onclick="() => ConfirmRevoke(session)">
                                    Revoke
                                </button>
                            }
                            else
                            {
                                <span class="badge bg-info">Current</span>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
</div>

<!-- Revoke Confirmation Dialog -->
@if (_sessionToRevoke is not null)
{
    <div class="modal d-block" tabindex="-1" style="background-color:rgba(0,0,0,0.5)">
        <div class="modal-dialog">
            <div class="modal-content">
                <div class="modal-header">
                    <h5 class="modal-title">Revoke Session</h5>
                    <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
                </div>
                <div class="modal-body">
                    <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
                </div>
                <div class="modal-footer">
                    <button type="button" class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                    <button type="button" class="btn btn-danger" @onclick="RevokeConfirmed">Revoke Session</button>
                </div>
            </div>
        </div>
    </div>
}

@code {
    private SecuritySettings? _settings;
    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private ActiveSession? _sessionToRevoke;
    private string? _message;
    private string _messageClass = "alert-success";

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = _settings.TwoFactorEnabled;
    }

    private async Task UpdatePassword()
    {
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            _message = "New password cannot be empty.";
            _messageClass = "alert-danger";
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            _message = "New password and confirmation do not match.";
            _messageClass = "alert-danger";
            return;
        }

        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _message = "Password updated successfully!";
        _messageClass = "alert-success";
        _settings = await SettingsService.GetSecuritySettingsAsync();
    }

    private void ConfirmRevoke(ActiveSession session)
    {
        _sessionToRevoke = session;
    }

    private void CancelRevoke()
    {
        _sessionToRevoke = null;
    }

    private async Task RevokeConfirmed()
    {
        if (_sessionToRevoke is not null)
        {
            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
            _settings = await SettingsService.GetSecuritySettingsAsync();
            _sessionToRevoke = null;
            _message = "Session revoked.";
            _messageClass = "alert-success";
        }
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}
