@using sv_72663b5985b044be823036a3ba9bc5ac.Services
@inject ISettingsService SettingsService

@if (_settings is null)
{
    <p>Loading...</p>
    return;
}

<h4 class="mb-4">Appearance Settings</h4>

@if (!string.IsNullOrEmpty(_message))
{
    <div class="alert alert-success alert-dismissible fade show" role="alert">
        @_message
        <button type="button" class="btn-close" @onclick="() => _message = null"></button>
    </div>
}

<div class="row">
    <div class="col-md-7">
        <!-- Theme -->
        <div class="mb-4">
            <h6>Theme</h6>
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                           value="@theme" checked="@(_theme == theme)"
                           @onchange="() => _theme = theme" />
                    <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                </div>
            }
        </div>

        <!-- Font Size -->
        <div class="mb-4">
            <h6>Font Size</h6>
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <div class="form-check form-check-inline">
                    <input class="form-check-input" type="radio" name="fontSize" id="@($"size-{size}")"
                           value="@size" checked="@(_fontSize == size)"
                           @onchange="() => _fontSize = size" />
                    <label class="form-check-label" for="@($"size-{size}")">@size</label>
                </div>
            }
        </div>

        <!-- Language -->
        <div class="mb-4">
            <h6>Language</h6>
            <select class="form-select" style="max-width:250px" @bind="_language">
                <option value="English">English</option>
                <option value="Spanish">Spanish</option>
                <option value="French">French</option>
                <option value="German">German</option>
                <option value="Japanese">Japanese</option>
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="compactMode" @bind="_compactMode" />
                <label class="form-check-label" for="compactMode">Compact Mode</label>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
    </div>

    <!-- Live Preview -->
    <div class="col-md-5">
        <div class="border rounded p-3 @GetPreviewClasses()" style="@GetPreviewStyle()">
            <h6 class="mb-2">Live Preview</h6>
            <p class="@(_compactMode ? "mb-1" : "mb-3")">This is how your content will look with the selected settings.</p>
            <div class="@(_compactMode ? "mb-1" : "mb-2")">
                <span class="badge bg-primary me-1">Tag 1</span>
                <span class="badge bg-secondary me-1">Tag 2</span>
            </div>
            <button class="btn btn-sm btn-outline-primary">Sample Button</button>
        </div>
    </div>
</div>

@code {
    private AppearanceSettings? _settings;
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private string? _message;

    protected override async Task OnInitializedAsync()
    {
        _settings = await SettingsService.GetAppearanceAsync();
        _theme = _settings.Theme;
        _fontSize = _settings.FontSize;
        _language = _settings.Language;
        _compactMode = _settings.CompactMode;
    }

    private async Task SaveAppearance()
    {
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _settings = updated;
        _message = "Appearance settings saved!";
    }

    private string GetPreviewClasses()
    {
        var classes = _theme switch
        {
            "Dark" => "bg-dark text-light",
            _ => "bg-light text-dark"
        };
        return classes;
    }

    private string GetPreviewStyle()
    {
        var size = _fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        return $"font-size:{size};";
    }
}

